package com.geminiapp.chat;

/**
 * Корневые сертификаты, которым доверяет собственный TLS-клиент (LegacyTls).
 * Системное хранилище Android 1.x-2.x не содержит корней Google Trust Services,
 * поэтому нужный корень вшит в приложение. Формат: Base64 от DER.
 */
final class Roots {

    private Roots() {}

    static final String[] DER_BASE64 = {
        // GTS Root R1 (Google Trust Services LLC)
        "",
        // GTS Root R4 (ECDSA)
        "",
        // USERTrust ECC Certification Authority (github.com)
        "",
        // USERTrust RSA Certification Authority (github.com)
        "",
        // DigiCert Global Root G2
        ""
    };
}
